import{_ as d,C as a,o as r,c as s,j as t,a as n,E as i,a2 as l}from"./chunks/framework.sc8Z_ZE3.js";const L=JSON.parse('{"title":"Models","description":"","frontmatter":{},"headers":[],"relativePath":"install/models.md","filePath":"install/models.md"}'),h={name:"install/models.md"};function c(m,e,p,u,g,b){const o=a("Badge");return r(),s("div",null,[e[0]||(e[0]=t("h1",{id:"models",tabindex:"-1"},[n("Models "),t("a",{class:"header-anchor",href:"#models","aria-label":'Permalink to "Models"'},"​")],-1)),i(o,{type:"built",text:"Built"}),e[1]||(e[1]=l(' Every model call goes through the platform&#39;s gateway and <strong>LiteLLM</strong>: the bundled one, or an external LiteLLM gateway of your company. Coding agents on devices and runners never reach a model provider themselves.<h2 id="the-bundled-litellm" tabindex="-1">The bundled LiteLLM <a class="header-anchor" href="#the-bundled-litellm" aria-label="Permalink to &quot;The bundled LiteLLM&quot;">​</a></h2><p>LiteLLM (pinned, v1.82.0-stable) runs next to the platform, on its loopback only, with its own database and no UI or logging. You manage its models in Octryx AI, not in LiteLLM.</p><h2 id="admin-›-models" tabindex="-1">Admin › Models <a class="header-anchor" href="#admin-›-models" aria-label="Permalink to &quot;Admin › Models&quot;">​</a></h2><p><strong>Admin › Models</strong> lists the models in one table. You add, edit, test or remove a model there.</p><table tabindex="0"><thead><tr><th>Field</th><th>Means</th></tr></thead><tbody><tr><td>Provider type</td><td>Anthropic, OpenAI, AWS Bedrock, Azure OpenAI, Google Gemini, OpenRouter, Ollama, or an OpenAI-compatible endpoint</td></tr><tr><td>Model id</td><td>the provider&#39;s id of the model</td></tr><tr><td>Credential</td><td>the key, or the AWS credentials. It is stored <strong>only in LiteLLM</strong>, never in the platform&#39;s database</td></tr><tr><td>Name</td><td>what people see</td></tr><tr><td>Data class</td><td>the highest <a href="/docs/security/data-classes">data class</a> the model is cleared for</td></tr><tr><td>Context window</td><td>the model&#39;s context size</td></tr><tr><td>Prices</td><td>input and output price; <strong>both must be above 0</strong></td></tr><tr><td>Tools</td><td>the model&#39;s tool support</td></tr></tbody></table><p>A model that exists on only one side, in the platform or in LiteLLM, shows <strong>Needs configuration</strong>.</p><p><strong>Add provider</strong> adds only an <strong>external LiteLLM gateway</strong>: its models then appear like the bundled ones.</p><h3 id="aws-bedrock-with-temporary-credentials" tabindex="-1">AWS Bedrock with temporary credentials <a class="header-anchor" href="#aws-bedrock-with-temporary-credentials" aria-label="Permalink to &quot;AWS Bedrock with temporary credentials&quot;">​</a></h3><p>A Bedrock model takes temporary AWS credentials (AWS SSO, an assumed role) with their session token, also at the first start. Such credentials expire, and the model stops working then: enter new ones in <strong>Admin › Models</strong>, or use a long-lived key pair.</p><h3 id="codex" tabindex="-1">Codex <a class="header-anchor" href="#codex" aria-label="Permalink to &quot;Codex&quot;">​</a></h3><p>Codex works with a model added here: the platform turns LiteLLM&#39;s answers into the events Codex needs. See <a href="/docs/install/codex">Codex</a>.</p><h2 id="the-first-start" tabindex="-1">The first start <a class="header-anchor" href="#the-first-start" aria-label="Permalink to &quot;The first start&quot;">​</a></h2><p>The first start turns the model block in <code>.env</code> into a model of the bundled LiteLLM and makes it the default, <strong>once</strong>:</p><table tabindex="0"><thead><tr><th><code>LLM_PROVIDER</code></th><th>Also set</th></tr></thead><tbody><tr><td><code>anthropic</code></td><td><code>AGENT_DEFAULT_MODEL</code>, <code>LLM_API_KEY</code></td></tr><tr><td><code>openai</code> (any OpenAI-compatible endpoint)</td><td><code>AGENT_DEFAULT_MODEL</code>, <code>LLM_ENDPOINT_URL</code>, <code>LLM_API_KEY</code></td></tr><tr><td><code>bedrock</code></td><td><code>AGENT_DEFAULT_MODEL</code>, <code>AWS_REGION</code>, <code>AWS_ACCESS_KEY_ID</code>, <code>AWS_SECRET_ACCESS_KEY</code>, optionally <code>AWS_SESSION_TOKEN</code></td></tr><tr><td><code>openrouter</code></td><td><code>AGENT_DEFAULT_MODEL</code>, <code>OPENROUTER_API_KEY</code></td></tr></tbody></table><p>Any other value creates no model; the start log says so. Every other provider (Azure OpenAI, Google Gemini, Ollama, …) is added in <strong>Admin › Models</strong> after the first sign-in. After the first start, <code>.env</code> is no longer read for models.</p><h2 id="which-models-a-workspace-may-use" tabindex="-1">Which models a Workspace may use <a class="header-anchor" href="#which-models-a-workspace-may-use" aria-label="Permalink to &quot;Which models a Workspace may use&quot;">​</a></h2><p>A Workspace that never saved its model list may use <strong>every admitted model its data class clears</strong>. A turn without a chosen model takes the Workspace&#39;s first governed model.</p><h2 id="removed-in-0-0-2" tabindex="-1">Removed in 0.0.2 <a class="header-anchor" href="#removed-in-0-0-2" aria-label="Permalink to &quot;Removed in 0.0.2&quot;">​</a></h2><p>The direct provider drivers are gone: AWS Bedrock, GitHub Copilot, Google Gemini with its Google sign-in, OpenRouter, OpenAI-compatible and Ollama as drivers, with their admin sections, the local model setup and the Bedrock price sync. A provider row of a removed driver stops working: <strong>add the model again</strong> in <strong>Admin › Models</strong>. <strong>GitHub Copilot is not available</strong> in 0.0.2.</p><p>See <a href="/docs/install/upgrade#from-0-0-1-alpha-to-0-0-2">Upgrade</a>.</p><h2 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h2><p>Allow HTTPS from the platform to the providers your models use. See <a href="/docs/security/egress">Egress allowlist</a>.</p>',25))])}const f=d(h,[["render",c]]);export{L as __pageData,f as default};
